# PowerShell Configuration script for Chat Simulator
# This script updates environment variables based on port configuration

param(
    [int]$PythonPort = 5000,
    [int]$FrontendPort = 5173
)

# Update .env.local file
$envContent = @"
# Chat Simulator Configuration
# Generated by smart startup scripts

# Python GIF Generator Configuration
VITE_PYTHON_API_URL=http://localhost:$PythonPort
VITE_PYTHON_HEALTH_URL=http://localhost:$PythonPort/health
VITE_PYTHON_LOGS_URL=http://localhost:$PythonPort/logs

# Frontend Configuration
VITE_PORT=$FrontendPort
PORT=$FrontendPort

# Service Status
PYTHON_PORT=$PythonPort
FRONTEND_PORT=$FrontendPort
"@

$envContent | Out-File -FilePath ".env.local" -Encoding UTF8

Write-Host "Configuration updated:"
Write-Host "  Python API: http://localhost:$PythonPort"
Write-Host "  Frontend: http://localhost:$FrontendPort"
